<?php
function record_manual_inflow($input,$file=null,$stage=false){
 $pdo=db();$user=current_user();$pid=(int)($input['product_id']??0);active_product($pid);
 $date=$input['txn_date']??'';$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new Exception('Select a valid date.');
 $reference=$input['reference_kind']??'';if(!in_array($reference,['Return Order','Return From Borrowed'],true))throw new Exception('Select a valid Reference.');
 $order=trim($input['order_id']??'');if($order===''||strlen($order)>100)throw new Exception('Order ID / borrowed reference is required (maximum 100 characters).');
 $condition=$input['item_condition']??'';if(!in_array($condition,['Good Item','Damaged / Leak','For Repackaging'],true))throw new Exception('Select Item Condition.');if($condition==='For Repackaging')packaging_require();
 $platform=$input['destination_platform']??'';if(!in_array($platform,['Shopee','Lazada','TikTok'],true))throw new Exception('Select a valid destination / return platform.');
 $raw=$input['source_qty']??'';if(!is_numeric($raw)||(float)$raw<=0)throw new Exception('Quantity must be greater than zero.');$uom=trim($input['source_uom']??'pc');[$factor,$qty]=receipt_quantity((float)$raw,$uom);if($qty<=0||$qty>100000000)throw new Exception('Invalid inventory quantity.');
 $remarks=trim($input['remarks']??'');$type=$reference==='Return Order'?'Customer Return - Good':'Return From Borrowed';$attachment=null;$original=null;
 if(!empty($file['tmp_name'])){if(!in_array(strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)),['pdf','png','jpg','jpeg'],true))throw new Exception('Use PDF, JPG or PNG attachments.');$attachment=store_upload($file,'inflow_attachments','INFATT');$original=basename($file['name']);}
 $pdo->beginTransaction();try{
  $lock=$pdo->prepare('SELECT id FROM products WHERE id=? FOR UPDATE');$lock->execute([$pid]);$ref=next_ref('INF-MAN');
  $meta=['reference_kind'=>$reference,'condition'=>$condition,'destination'=>$condition==='Good Item'?$platform:'Non-Sellable','return_platform'=>$platform,'product_id'=>$pid,'source_qty'=>(float)$raw,'source_uom'=>$uom,'conversion_factor'=>$factor,'qty'=>$qty,'remarks'=>$remarks];
  $pdo->prepare('INSERT INTO inflow_batches(batch_ref,batch_type,source_name,reference_no,txn_date,attachment_path,original_filename,status,total_qty,result_json,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$ref,'Manual',$reference,$order,$date,$attachment,$original,$stage?'To Review':'Confirmed',$stage?0:$qty,json_encode($meta),$user['id']]);$bid=(int)$pdo->lastInsertId();
  if($stage){audit('Review manual inflow','Inflow Batch',$ref,'Pending allocation; no inventory added.');$pdo->commit();return $bid;}
  if($condition==='Good Item'){
   $pdo->prepare('INSERT INTO inflows(batch_id,txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$bid,$date,$order,$reference,$platform==='Warehouse'?'':$platform,$pid,(float)$raw,$uom,$factor,$qty,$type,$remarks,$user['id']]);
   if($platform!=='Warehouse'){adjust_platform_qty($platform,$pid,$qty);validate_allocation_total($pid);}
  }else{
   $pdo->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$date,$platform==='Warehouse'?'':$platform,$order,$pid,$qty,$condition==='For Repackaging'?'For Repackaging':'Damaged / Leak','For Review',$condition==='For Repackaging'?'Pending':'For Review',$reference==='Return Order'?'Customer Return':'Borrowed Return',0,$remarks,$user['id']]);$meta['non_sellable_id']=(int)$pdo->lastInsertId();if($condition==='For Repackaging')packaging_initialize($meta['non_sellable_id']);
   $pdo->prepare('UPDATE inflow_batches SET result_json=? WHERE id=?')->execute([json_encode($meta),$bid]);
  }
  audit('Add inflow','Inflow Batch',$ref,"$condition +$qty pcs; {$meta['destination']}; $reference; $order");$pdo->commit();return $bid;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function inflow_page(){
 $history=($_GET['history']??'')==='all';$tab=$_GET['entry']??'manual';if(!in_array($tab,['manual','bulk','receipt'],true))$tab='manual';
 echo '<div class="page-head"><div><h1>Inflow'.($history?' History':'').'</h1><p>Record incoming stock and review inflow transactions.</p></div>'.($history?'<a class="btn ghost" href="?page=inflow">Back to Inflow</a>':'').'</div>';
 inflow_search_form();$isSearch=inflow_search_active();try{$filter=inflow_history_query();}catch(Throwable $ex){echo '<div class="alert danger">'.e($ex->getMessage()).'</div>';return;}ob_start();
 if(!$history){echo '<div class="card"><div class="tabs entry-tabs">';foreach(['manual'=>'Manual Inflow','bulk'=>'Bulk Inflow Upload','receipt'=>'Receipt / Packing Slip Upload'] as $key=>$label)echo '<a class="tab '.($tab===$key?'active':'').'" href="'.($key==='cancelled'?'?page=cancelled_orders':'?page=inflow&entry='.$key).'">'.e($label).'</a>';echo '</div>';
 if($tab==='manual'){
  receiving_page();
 }elseif($tab==='bulk')echo '<h3>Bulk Inflow Upload</h3><p>Upload a prepared product and quantity list. Upload, review, allocate incoming units, then Confirm Inflow to add stock. You can Cancel Upload before confirmation.</p><a class="btn ghost" href="download.php?type=supplier_inflow_template">Download Template</a><form method="post" enctype="multipart/form-data" action="actions.php" class="stack"><input type="hidden" name="action" value="upload_inflow"><label>Supplier / Source<input name="supplier" maxlength="180" required></label><input type="hidden" name="return" value="inflow&entry=bulk"><input type="file" name="file" accept=".xlsx" required><div class="modal-actions"><button type="button" class="btn ghost" data-cancel-inflow-form>Cancel</button><button class="btn primary">Upload &amp; Review</button></div></form>';
 else echo '<h3>Receipt / Packing Slip Upload</h3><p>Upload a PDF and review every extracted item and its platform allocation before confirming stock.</p><form method="post" enctype="multipart/form-data" action="actions.php" class="stack"><input type="hidden" name="action" value="upload_receipt"><label>Supplier / Source<input name="supplier" maxlength="180" required></label><input type="hidden" name="return" value="receipt_review"><input type="file" name="receipt" accept=".pdf" required><div class="modal-actions"><button type="button" class="btn ghost" data-cancel-inflow-form>Cancel</button><button class="btn primary">Upload Receipt PDF</button></div></form>';
 if($tab==='bulk')echo '<hr><h3>Excel Order Returns</h3><p>Use Order ID and the original platform. No Return ID is required. Good, damaged and For Repackaging quantities are checked against the remaining original order quantity.</p><a class="btn secondary" href="download.php?type=return_template">Download Order Return Template</a><form method="post" enctype="multipart/form-data" action="actions.php" class="stack"><input type="hidden" name="action" value="return_upload"><input type="hidden" name="return" value="inflow&entry=bulk"><input type="file" name="file" accept=".xlsx" required><button class="btn primary">Upload Returns &amp; Review</button></form>';
 echo '</div>';}
 $entryHtml=ob_get_clean();if(!$isSearch)echo $entryHtml;
 $offset=max(0,(int)($_GET['offset']??0));$limit=10;$q=db()->prepare('SELECT COUNT(*)'.$filter['sql']);$q->execute($filter['args']);$total=(int)$q->fetchColumn();
 echo '<div class="card table-wrap inflow-results">';if($isSearch)inflow_search_summary($total);else echo '<div class="card-head"><div><h3>'.($history?'Inflow Transaction History':'Recent Inflow Batches').'</h3><span class="muted small">'.($history?'All inflow transactions; 10 per page.':'10 transactions per page').'</span></div>'.(!$history?'<a class="btn ghost" href="?page=inflow&history=all">View all</a>':'').'</div>';echo '<div class="inflow-results-table"><table class="table"><tr><th>Date</th><th>Order ID / Reference</th><th>Type</th><th>Condition</th><th>Destination</th><th>Total Qty</th><th>Supplier / Staff</th><th>Status</th><th>Action</th></tr>';
 $historyQuery=db()->prepare("SELECT b.*,u.name processed_by".$filter['sql']." ORDER BY b.id DESC LIMIT $limit OFFSET $offset");$historyQuery->execute($filter['args']);foreach($historyQuery as $r){$meta=json_decode($r['result_json']??'',true)?:[];$condition=$meta['condition']??($r['status']==='Confirmed'?'Good Item':'Pending review');$destination=$meta['destination']??($r['status']==='Confirmed'?'Legacy / see details':'Pending review');$view=$r['batch_type']==='Borrowed Return'?'borrowed':(in_array($r['batch_type'],['Order Return','Cancelled Order'],true)&&isset($meta['return_batch_id'])?($r['batch_type']==='Cancelled Order'?'cancelled_orders':'order_return'):($r['batch_type']==='Receipt PDF'&&$r['status']!=='Confirmed'?'receipt_review':'inflow_batch'));$viewId=$meta['borrow_id']??$meta['return_batch_id']??$r['id'];if(in_array($view,['order_return','cancelled_orders'],true)){try{$rb=return_batch((int)$viewId);$rr=json_decode($rb['rows_json'],true);if(!empty($rr[0]['manual_lookup']))$view='manual_receiving';}catch(Throwable $ex){}}echo '<tr><td>'.e($r['txn_date']).'</td><td>'.e($r['reference_no']?:$r['batch_ref']).'<div class="muted small">'.e($r['batch_ref']).'</div></td><td>'.e($meta['reference_kind']??$r['batch_type']).'</td><td>'.e($condition).'</td><td>'.e($destination).'</td><td>'.(int)$r['total_qty'].' pcs</td><td>'.e($r['source_name']).'<br>'.e($r['processed_by']??'').'</td><td>'.return_inflow_review_label($r,$meta).'</td><td><a class="btn ghost sm" href="?page='.$view.'&id='.$viewId.'">View</a>'.inflow_error_review_link($r).'</td></tr>';}
 if(!$total)echo '<tr><td colspan="9">No inflow transactions match these filters.</td></tr>';echo '</table></div><div class="inflow-results-footer muted small">'.($total?'Showing '.($offset+1).'–'.min($offset+$limit,$total).' of '.$total.' results':'0 results').'</div></div>';echo rs8_pagination($total,$offset,10,array_replace($_GET,['page'=>'inflow']));
 if($isSearch&&!$history)echo '<div class="inflow-new-entry"><h2>New Inflow</h2>'.$entryHtml.'</div>';
}
function manual_inflow_details($batch){$meta=json_decode($batch['result_json']??'',true)?:[];if(!isset($meta['condition']))return;$query=db()->prepare('SELECT name FROM products WHERE id=?');$query->execute([$meta['product_id']]);$p=$query->fetch()?:['name'=>'Archived product'];echo '<div class="card"><h3>Incoming Item</h3><table class="table"><tr><th>Product</th><th>Reference</th><th>Condition</th><th>Destination</th><th>Quantity</th></tr><tr><td>'.e($p['name']).'</td><td>'.e($meta['reference_kind']).'</td><td>'.e($meta['condition']).'</td><td>'.e($meta['destination']).'</td><td>'.(int)$meta['qty'].' pcs</td></tr></table><p>'.e($meta['remarks']).'</p>';if(isset($meta['non_sellable_id']))echo '<a class="btn ghost" href="?page=nonsellable_detail&id='.(int)$meta['non_sellable_id'].'">View Non-Sellable Record</a>';echo '</div>';}
